"""Freeze the supported backend scope, verify actual frozen CLI, publish handoff."""
import copy,json,sys,sqlite3,subprocess,time,socket,urllib.request,urllib.error,importlib.metadata,csv,difflib
from pathlib import Path
from support import ROOT,PACKAGE,FUNCTIONAL,read,save,filehash,ResearchError
from contracts import TwinReview
from review_gate import reviewed_metric_twin
from fixtures import controlled_registration

READY=ROOT/'PP1_READINESS_20261022';FINAL=READY/'10_FINAL_VERIFICATION';OUT=PACKAGE/'outputs/HANDOFF_V1'
def rel(path):return str(Path(path).relative_to(ROOT)).replace('\\','/')
def main():
    close=OUT/'closeout';close.mkdir()
    regression=read(PACKAGE/'outputs/HANDOFF_FINAL_REGRESSION_49/TEST_RESULTS.json');assert regression['passed']==49 and not regression['failures']
    new=read(OUT/'release_acceptance/TEST_RESULTS.json');assert new['passed']==30 and not new['failures']
    supplemental=read(OUT/'release_acceptance/SUPPLEMENTAL_RETEST/TEST_RESULTS.json');assert supplemental['passed']==4
    comparison=read(OUT/'comparison/FAIR_COMPARISON.json');assert len(comparison['records'])==10 and all(r['evaluations']==1680 for r in comparison['records'])
    for p in PACKAGE.glob('*.py'):compile(p.read_text(encoding='utf-8'),str(p),'exec')
    original=read(READY/'00_PROJECT_CONTROL/SOURCE_SHA256_BEFORE.json');assert len(original)==317 and all(filehash(ROOT/p)==sha for p,sha in original.items())
    freeze_old=read(PACKAGE/'outputs/CLOSEOUT/FREEZE_34_FINAL.json');assert len(freeze_old)==34 and all(filehash(ROOT/r['path'])==r['expected'] for r in freeze_old)
    inventory=list(csv.DictReader((READY/'00_PROJECT_CONTROL/FILE_INVENTORY.csv').open()));assert len(inventory)==97647 and all((ROOT/r['path']).is_file() and (ROOT/r['path']).stat().st_size==int(r['bytes']) for r in inventory)
    oldmanifest=read(FINAL/'READINESS_ARTIFACT_SHA256_V2.json');presentations=[p for p in oldmanifest if p.replace('\\','/').startswith('09_PRESENTATION/')];assert len(presentations)==29 and all(filehash(READY/p)==oldmanifest[p] for p in presentations)
    integrity={'targeted_original_hashes_unchanged':317,'freeze_integration_matches':34,'original_inventory_files_present_same_size':97647,'presentation_hashes_unchanged':29,'full_dataset_bytewise_hash_baseline':False}
    save(close/'ORIGINAL_INTEGRITY.json',integrity)
    # Demonstrate specific fixes against the preserved pre-change implementation.
    namespace={'__file__':str(OUT/'before/review_gate.py')};exec(compile((OUT/'before/review_gate.py').read_text(),str(OUT/'before/review_gate.py'),'exec'),namespace)
    base=controlled_registration(close/'before_after_fixture');cases=[]
    for name in ['candidate_source_dimensions','unprovided_evidence_file']:
        q=copy.deepcopy(base)
        if name=='candidate_source_dimensions':
            from support import digest
            q['candidate_bundle']['source']=copy.deepcopy(q['candidate_bundle']['source']);q['candidate_bundle']['source']['width_pixels']=999;q['review']['candidate_bundle_sha256']=digest(q['candidate_bundle'])
        else:q['review']['evidence_artifacts']=[{'evidence_id':'NOT_PROVIDED','path':str(close/'not_provided.pdf'),'sha256':'0'*64,'source_sha256':q['review']['source']['sha256']}]
        record=TwinReview(**q['review']);old=namespace['reviewed_metric_twin'](record,q['candidate_bundle']);assert old['schema']=='COMPONENT1_METRIC_TWIN_V1'
        try:reviewed_metric_twin(record,q['candidate_bundle']);raise AssertionError('Negative control accepted')
        except ResearchError as exc:cases.append({'case':name,'before':'ACCEPTED','after':'REJECTED','reason':exc.code,'domain':'controlled_synthetic_adversarial_fixture'})
    save(close/'BEFORE_AFTER_DEFECTS.json',cases)
    # Pin complete source of this isolated implementation, actual model adapters,
    # independent checker and both trained checkpoints. Freeze is a drift check,
    # not authentication or a guarantee of environmental reproducibility.
    runtime=list(PACKAGE.glob('*.py'))+[FUNCTIONAL/'prediction_bridge_v3.py',FUNCTIONAL/'independent_geometry.py',ROOT/'PP1_STAGE_E_EVENT_LAYOUT_V2/backend/venue_unet_inference_v2.py',ROOT/'02_GENERATED_RESEARCH_DATA/STAGE_B_PP1_BASELINE/best_unet_resnet18.pt',ROOT/'02_GENERATED_RESEARCH_DATA/STAGE_C_OBJECTS/C3_22_PP1_PRETRAINED_CONTROLLED_PILOT_V1/yolov8n_v3_960_pretrained_v1/weights/best.pt']
    # Include research dependencies read/imported by engine adapters, via the
    # preexisting targeted baseline as well. No original source is rewritten.
    runtime += [ROOT/p for p in original if str(p).replace('\\','/').endswith('.py')]
    runtime={rel(p):filehash(p) for p in runtime}
    versions={name:importlib.metadata.version(name) for name in ['fastapi','pydantic','uvicorn','numpy','scipy','shapely','opencv-python','torch','torchvision','segmentation-models-pytorch','ultralytics','pymoo','Pillow']}
    save(close/'ENVIRONMENT.json',{'python':sys.version,'packages':versions,'new_dependencies_installed':False,'optional_plugin_autoinstall_disabled':True})
    save(PACKAGE/'BACKEND_FREEZE_V1.json',{'api_version':'1.1.0','scope':'Supported local PP1 image-candidate and controlled metric-layout research backend; genuine real-venue acceptance pending','runtime_sha256':runtime,'environment_record':rel(close/'ENVIRONMENT.json'),'schema_file':rel(OUT/'release_acceptance/OPENAPI_V1.json'),'schema_sha256':filehash(OUT/'release_acceptance/OPENAPI_V1.json'),'test_results':{rel(p):filehash(p) for p in [PACKAGE/'outputs/HANDOFF_FINAL_REGRESSION_49/TEST_RESULTS.json',OUT/'release_acceptance/TEST_RESULTS.json',OUT/'release_acceptance/SUPPLEMENTAL_RETEST/TEST_RESULTS.json']},'unsupported_objectives_retained_as_future_work':['S-GCN','weather','real-domain validation','multiple-group adaptive search','guest addition']})
    command=[sys.executable,'-B',str(PACKAGE/'research.py'),'verify-freeze'];verified=subprocess.run(command,cwd=ROOT,capture_output=True,text=True);assert verified.returncode==0,verified.stderr
    save(close/'FREEZE_VERIFICATION.json',{'command':command,'exit_code':verified.returncode,'stdout':verified.stdout,'runtime_files':len(runtime)})
    # Actual frozen executable, TCP transport and immutable schema reproduction.
    sock=socket.socket();sock.bind(('127.0.0.1',0));port=sock.getsockname()[1];sock.close()
    cmd=[sys.executable,'-B',str(PACKAGE/'research.py'),'serve','--db',str(close/'frozen_tcp.sqlite3'),'--port',str(port)]
    def http(path,body=None):
        data=json.dumps(body).encode() if body is not None else None
        request=urllib.request.Request(f'http://127.0.0.1:{port}'+path,data=data,headers={'Content-Type':'application/json'})
        with urllib.request.urlopen(request,timeout=60) as r:return json.load(r)
    with (close/'FROZEN_SERVER_LOG.txt').open('x') as log:
        process=subprocess.Popen(cmd,cwd=ROOT,stdout=log,stderr=subprocess.STDOUT,creationflags=subprocess.CREATE_NO_WINDOW)
        try:
            for _ in range(200):
                try:health=http('/health');break
                except (OSError,urllib.error.URLError):
                    if process.poll() is not None:raise RuntimeError('Frozen server exited')
                    time.sleep(.1)
            else:raise RuntimeError('Frozen server startup timed out')
            assert http('/openapi.json')==read(OUT/'release_acceptance/OPENAPI_V1.json')
            registration=read(OUT/'release_acceptance/REGISTER_REQUEST.json');t=http('/twins',registration);request=read(OUT/'release_acceptance/INITIAL_REQUEST.json');request['twin_sha256']=t['twin_sha256'];response=http('/optimize',request);assert response['status']=='success' and response['optimizer_evaluations']==1200
            retrieved=http('/runs/'+response['run_id']);assert retrieved['response']==response
            save(close/'FROZEN_TCP_INITIAL_REQUEST.json',request);save(close/'FROZEN_TCP_INITIAL_RESPONSE.json',response)
            tcp={'command':cmd,'health':health,'identical_openapi_schema':True,'initial_alternatives':len(response['candidate_layouts']),'retrieval_exact_match':True,'server_stopped_after_test':True};save(close/'FROZEN_TCP_RESULT.json',tcp)
        finally:process.terminate();process.wait(timeout=10)
    actual=read(OUT/'release_acceptance/ACTUAL_MODEL_API_RESPONSE.json');analysis=actual['analysis_id'];scope='READY_FOR_FRONTEND_INTEGRATION_OF_SUPPORTED_LOCAL_PP1_SCOPE'
    commands=[{'command':'.venv\\Scripts\\python.exe -B PP1_READINESS_20261022/PP1_EXECUTABLE_V1/tests_execution.py --output-name HANDOFF_FINAL_REGRESSION_49','exit_code':0,'log':rel(OUT/'FINAL_REGRESSION_49_LOG.txt')},{'command':'.venv\\Scripts\\python.exe -B PP1_READINESS_20261022/PP1_EXECUTABLE_V1/handoff_tests.py --name release_acceptance','exit_code':0,'log':rel(OUT/'RELEASE_ACCEPTANCE_LOG.txt')},{'command':'.venv\\Scripts\\python.exe -B PP1_READINESS_20261022/PP1_EXECUTABLE_V1/handoff_comparison.py','exit_code':0,'log':rel(OUT/'COMPARISON_LOG.txt')},{'command':'.venv\\Scripts\\python.exe -B PP1_READINESS_20261022/PP1_EXECUTABLE_V1/close_handoff.py','result':'Integrity, before/after probes, schema freeze and actual frozen TCP run asserted before report creation.'},{'command':command,'exit_code':0,'evidence':rel(close/'FREEZE_VERIFICATION.json')},{'command':cmd,'result':'Frozen TCP startup/registration/optimization/retrieval succeeded; own server stopped.'}]
    endpoints=[
      ['POST','/images','application/octet-stream raw PNG/JPEG bytes','ImageReceipt','20 MiB / 16 million pixel limit; preserves input bytes/hash; no physical provenance inference.'],
      ['POST','/analyses','Analyze {image_path}','AnalysisReceipt','Actual U-Net and YOLO; saved candidates/overlays; always review_required.'],
      ['GET','/analyses/{analysis_id}','32-character server-issued ID','AnalysisReceipt','Rechecks saved artifact hashes; survives app recreation.'],
      ['GET','/analyses/{analysis_id}/artifacts/{filename}','Server-returned artifact URL','PNG or JSON file','Manifest whitelist only; corrupt/missing analysis rejected.'],
      ['POST','/twins','Register {review: TwinReview, candidate_bundle: object}','TwinReceipt','Source/candidate/evidence/calibration/geometry gate; no auto approval.'],
      ['GET','/twins/{venue_id}/versions/{version}','venue ID and version','TwinReceipt','Current immutable registered version only; stale version explicitly rejected.'],
      ['POST','/optimize','Optimize','Success | NonSuccess','Check logical status even for HTTP 200; final independent validation mandatory.'],
      ['GET','/runs/{run_id}','server run ID','StoredRun','Exact saved request/response, integrity checks.'],
      ['GET','/runs','none','RunIndex','Latest 100 rows; IDs, statuses and response hashes.'],
      ['POST','/runs/{run_id}/approve','Approve','ApprovalReceipt','Bound layout SHA/Twin/version; local explicit approval input.'],
      ['POST','/approvals/{approval_id}/revoke','Revoke','RevocationReceipt','Revoked reference cannot yield a successful saved revision.'],
      ['GET','/contracts','none','Named JSON schemas + api_version','Detailed request/response schemas; OpenAPI includes nested layout/object schema.'],
      ['GET','/health','none','Health','Local service status and DB location; not model/real-venue accuracy evidence.']]
    limitations=['No genuine real-venue reviewed/calibrated metric input or authenticated planner identity supplied. Real image-to-final-layout success remains unverified.','Evidence gate verifies files, hashes, source binding and referenced IDs. It cannot determine whether an uploaded statement, photograph or measurement is truthful, whether a person supplied it, or whether physical measurements are accurate. Invented but internally consistent evidence cannot be ruled out by software alone.','All successful review/approval fixtures are explicitly controlled/simulated. External-reference missing/hash/source checks are adversarial tests, not a genuine external positive case.','U-Net foreground metric ignores raw background, with train/test and train/validation duplicate leakage risks; transformed/source ancestry unresolved. No data/split/weight/retraining changes.','YOLO accuracy evidence remains synthetic; buffet has zero held-out support and temporary_partition AP50 zero. Actual upload inference returns 10 structural candidates and zero detections, not proof of correct real understanding.','S-GCN, weather, planner feedback learning, counterfactual/human XAI studies, multi-group adaptation, guest addition and full CAD/PDF support are unfinished original research objectives.','Only Wedding with exact eight-seat groups is supported; schema allows guest counts up to 240, but feasibility and full count/venue coverage are not guaranteed. Real-domain adaptive permission scope is expressly rejected.','Original PermissionV1 legacy suite still fails due obsolete V1 config against V2 validator; isolated migrated five-check fixture passes. This release does not claim every historical script passes.','Current server is localhost, synchronous research execution; no production identity/authentication, multi-user authorization, horizontal worker coordination, performance SLA or safety certification.','Candidate source metadata is exact-match: use the returned source block and canonical hash function; no normalization/mutation of a saved candidate bundle. Old DB Twin hashes must not be edited to match new schema defaults. Use a fresh DB or explicit new Twin version.']
    failed=['First new-test launch mutated shared fixture source metadata in both review and candidate; the gate correctly rejected SOURCE_DIMENSION_MISMATCH. Test corrected to independently mutate candidate metadata; original failed log retained.','A later invalid-image test triggered the installed Ultralytics PIL monkey patch to attempt pi-heif auto-install. Execution was stopped; pip attempts failed, pi-heif is not installed. Auto-install is disabled and intake retains a PNG/JPEG Pillow reader. Final invalid-image test passes without plugin installation.','Another rerun hit exclusive-write FileExistsError while exporting schemas to the earlier test directory. Export paths were moved inside each uniquely named test output directory; failed run retained; final 30-case run passes.']
    acceptance={'version':'PP1_BACKEND_FUNCTIONAL_ACCEPTANCE_V1','api_version':'1.1.0','status':scope,'frontend_developed':False,'full_research_complete':False,'real_venue_end_to_end_verified':False,'genuine_external_positive_review_tested':False,'original_sources_data_weights_unchanged':True,'integrity':integrity,'regression_tests':regression,'handoff_tests':new,'reused_supplemental_tests':supplemental,'test_count_note':'30 handoff cases include a wrapper that reexecutes the four supplemental tests; do not add wrapper and nested checks as independent coverage. Earlier repeated 49/28/30 runs are not extra unique tests.','fair_comparison':comparison,'before_after_defects':cases,'endpoints':endpoints,'schemas':{'openapi':rel(OUT/'release_acceptance/OPENAPI_V1.json'),'contracts':rel(OUT/'release_acceptance/API_CONTRACTS_V1.json'),'canonical_hash':'SHA256 of UTF-8 json.dumps(value, sort_keys=True, separators=(comma, colon), allow_nan=False); use support.digest; no whitespace/newline in canonical form'},'actual_model_analysis_id':analysis,'actual_model_outputs':rel(PACKAGE/'outputs/API_ANALYSES'/analysis),'frozen_tcp_test':tcp,'freeze_manifest':rel(PACKAGE/'BACKEND_FREEZE_V1.json'),'commands':commands,'limitations':limitations,'failed_attempts_and_corrections':failed,'remaining_pp1_input':'Genuine usable boundary/fixed geometry, measured calibration controls, supporting source-bound artifacts and explicit reviewer/requirement/approval records. Do not fabricate them.','recommended_next_decision':'Backend supports a scoped frontend integration decision. Stop now; user decides whether frontend development begins. Original research objectives remain on the roadmap.'}
    save(FINAL/'PP1_BACKEND_FUNCTIONAL_ACCEPTANCE_V1.json',acceptance)
    # Report is the requested backend handoff, not a frontend or presentation.
    text=['# PP1 backend → frontend handoff V1','','**Status: '+scope+'.** API version **1.1.0**. Backend scope is frozen and the executable CLI checks source/dependency hashes before running. No frontend, React, presentation or cosmetic work was performed.','','The supported local PP1 workflows are executable and independently checked. The real-venue image-to-final-layout research claim remains unverified because genuine measured/reviewed inputs are absent. This is a scoped backend handoff; full research completion is not claimed.','','## Acceptance evidence','','- **49/49 existing acceptance tests PASS** on final optimizer/review/API code.','- **30/30 handoff cases PASS**, including actual model inference/upload/artifact retrieval, independent metric transform, source metadata/evidence rejection, context effects, Pareto replay, revocation during real search and response-contract/XAI checks.','- **4/4 original supplemental checks rerun successfully inside one of those 30 cases**; do not add nested checks as separate coverage.','- A fresh **frozen CLI TCP server** reproduced the exact OpenAPI contract and completed registration → initial optimization → persisted retrieval. It returned eight alternatives and was stopped after testing.','- Five paired seeds × two sampling methods, each with 1680 evaluations, were rerun with the same one-group reference and constraints.','- Original source/checkpoint/artifact hashes **317/317 unchanged**, freeze/integration matches **34/34**; original inventory **97,647** files remain at recorded sizes; **29/29** presentation hashes unchanged. This is not a full raw-dataset bytewise baseline.','',f"Raw tests: `{rel(PACKAGE/'outputs/HANDOFF_FINAL_REGRESSION_49/TEST_RESULTS.json')}`; `{rel(OUT/'release_acceptance/TEST_RESULTS.json')}`; nested supplemental: `{rel(OUT/'release_acceptance/SUPPLEMENTAL_RETEST/TEST_RESULTS.json')}`.",'',f"Independent acceptance JSON: `{rel(FINAL/'PP1_BACKEND_FUNCTIONAL_ACCEPTANCE_V1.json')}`. Before/after negative-control evidence: `{rel(close/'BEFORE_AFTER_DEFECTS.json')}`.",'','## Executable entry point','','From `C:\\My Research Component`:','','```powershell','.venv\\Scripts\\python.exe -B PP1_READINESS_20261022/PP1_EXECUTABLE_V1/research.py verify-freeze','.venv\\Scripts\\python.exe -B PP1_READINESS_20261022/PP1_EXECUTABLE_V1/research.py serve --db PP1_READINESS_20261022/PP1_EXECUTABLE_V1/outputs/HANDOFF_DEMO_001/research.sqlite3 --port 8765','```','','Open `http://127.0.0.1:8765/docs`. Keep new demonstration databases/output directories separate from historical evidence. `research.py demo --out <new-output-directory>` still executes the controlled initial/adaptive/denied workflow. The runbook remains at `PP1_EXECUTABLE_V1/RUNBOOK.md`.','','## Verified API endpoints','','| Method | Endpoint | Request | Response schema | Behavior |','|---|---|---|---|---|']
    text += ['| '+' | '.join(r).replace('Success | NonSuccess','Success / NonSuccess')+' |' for r in endpoints]
    text += ['','## Request/response schemas and hashes','',f"Canonical machine contract: `{rel(OUT/'release_acceptance/OPENAPI_V1.json')}`. Named JSON schemas: `{rel(OUT/'release_acceptance/API_CONTRACTS_V1.json')}`. `/openapi.json` on the frozen server matched the saved file exactly. Runtime schema models are in `contracts.py`, `responses.py`, `analysis_api.py` and `api.py`.",'','- JSON input models forbid extra fields, nonfinite numerical values and blank string fields. Required quantities and supported constraint names are explicit.','- `Register` contains `review` and the unchanged `candidate_bundle`. `TwinReview` requires source metadata, bundle hash, calibration, boundary, fixed objects and review decision. Optional `evidence_artifacts` entries contain `evidence_id`, workspace `path`, file `sha256` and matching `source_sha256`. For external (`real_source`) review every measurement/review/object-decision reference must resolve to such a supplied artifact.','- `Optimize` requires contract ID `COMPONENT1_PP1_EXECUTABLE_V1`, mode, registered venue ID/version/Twin hash, structured client/planner requirements and seed. Revision modes require matching reference run/layout/layout hash/approval ID and explicit scoped per-action permissions.','- `Success` contains real returned layout polygons, stable object/group IDs, independently verified metrics, selected layout ID, source/Twin hashes, resolved requirements, actual evaluation count, provenance and response-bound XAI. Layout objects use `class`, `group_id` and `footprint_coordinates_m`; all geometry is metric.','- `NonSuccess` has explicit `status`, `reason`, `details`, empty `candidate_layouts`, actual evaluations consumed and bound denial explanation. An optimizer failure to find feasible solutions is not a global infeasibility proof.','- HTTP 200 `/optimize` can carry `success`, `denied`, `rejected`, `infeasible` or `error`; always inspect status. HTTP 422 is either `{reason, details}` for a gate/domain failure, or a persisted `NonSuccess` for a request-schema rejection. New image-intake/analysis gate errors are not falsely reported as optimizer runs.','- `/runs` is limited to the latest 100 rows; use a saved run ID for exact retrieval. Twin reads reject stale versions explicitly. Schema/error routes are localhost research contracts, not production access control.','- Canonical layout/Twin hashes use `support.digest`: SHA256 of sorted-key compact UTF-8 JSON, `allow_nan=False`. Never hash pretty-printed file bytes as a layout hash. Use `verification[layout_id].layout_sha256` for approval.','- Exact request/response examples, including real generated run IDs, are in `outputs/HANDOFF_V1/release_acceptance/REGISTER_REQUEST.json`, `INITIAL_REQUEST.json`, `INITIAL_RESPONSE.json`, `ADAPTIVE_REQUEST.json`, `ADAPTIVE_RESPONSE.json`. They belong to that test database; approval IDs must be created afresh in another database. Guest-change examples remain in `outputs/HANDOFF_FINAL_REGRESSION_49/GUEST_REDUCTION_REQUEST.json` and response.','','## Supported workflows','','1. **Image → model candidates → pending review**: POST raw PNG/JPEG to `/images`; send its returned `image_path` to `/analyses`; retrieve candidate bundle, preview artifact URLs and pending review template. Actual trained checkpoints execute. No metric scale, usable boundary or approval is invented.','2. **Supplied review → metric Twin**: retain returned source/candidate data. A genuine reviewer supplies boundary, fixed geometry, two distinct consistent known-distance controls, origin, decisions and source-bound evidence artifacts. POST `/twins`. Missing, mismatched, stale or unsupported input is rejected. Positive automated evidence tests use explicitly synthetic generator records; no genuine external planner record was available.','3. **Metric Twin + requirements → initial NSGA-II**: structured approved client/planner input, Wedding, exactly eight seats/table, supported quantities and constraints. Hard limits affect feasibility; supported soft preference selects among actual feasible nondominated candidates. Original NSGA-II operators/population/generations are retained in isolated copies.','4. **Approved reference → single-group adaptive revision**: create an explicit scoped approval against the selected run/layout/version/hash; submit one affected group and move permission. Current live adaptive support is controlled-synthetic only. Unaffected groups and individual object polygons stay locked. Revoked/stale/foreign approvals cannot be saved as successful revision results.','5. **Permitted guest reduction**: identify and permit removed groups explicitly. Retained group and object IDs/polygons remain unchanged, including noncontiguous IDs. Example 160 → 120 guests returns 138 objects with zero evolutionary evaluations. Addition is explicitly unsupported.','6. **Verified output → XAI → SQLite → retrieval**: every returned candidate is independently checked before successful write. Explanations bind request/run/response/layout, reflect measured tradeoffs and report denials honestly. Source/evidence integrity and reference/version freshness are rechecked; final success persistence checks concurrent revocation/version change.','','## Corrections made in this release','','- Candidate hash/source SHA alone previously allowed inconsistent candidate dimensions/domain/path. Full source metadata and valid unique candidate IDs are now checked. Preserved old-gate probes accepted inconsistent candidate metadata; corrected gate rejects it.','- Evidence text was previously accepted without a supplied artifact. External references must now resolve to existing source-bound hashed files, checked at registration and optimization and before successful persistence. Declared missing evidence on a controlled negative-control fixture was accepted by the old gate and rejected by this release.','- Version registration and final approval version checks use SQLite write transactions; successful persistence checks source/evidence freshness and approval revocation after actual search.','- Missing registered source and nonfinite untrusted candidate JSON return declared rejections instead of server errors.','- Added durable actual-model image API, artifact integrity/readback and immutable metric-Twin retrieval. Explicit request/response envelopes and nested layout/object schemas are exported through OpenAPI.','- Optional dependency auto-install is disabled. PNG/JPEG validation keeps the original Pillow reader, avoiding the third-party HEIF-install behavior on invalid input.','','## Context and optimization evidence','','A hard maximum-movement limit of zero restricts the feasible initial results to zero assignment movement and changes the returned candidate count. Changing stage-proximity to minimum-disruption soft preference keeps the exact candidate geometry set and changes the selected layout. This is transparent selection behavior, not learned S-GCN preference weighting. Quantities, approvals, conflicts, protected IDs and unsupported hard fields have explicit rejection tests.','','Returned Pareto vectors were independently recomputed from raw group centers and stage geometry, with assignment movement for initial design and stable-ID movement for adaptive revision; no optimizer measurement helper was used in those checks. Nondominance is verified among the returned candidate set; global optimality is not claimed. Individual-object geometry, lock and poisoned-output tests remain mandatory in the original regression.','','## Fair comparisons and claim limits','',f"New raw runs and paired results: `{rel(OUT/'comparison/FAIR_COMPARISON.json')}`. Five seeds, same controlled reference/Twin, one movable group, same constraints/population/operators and 1680 evaluations per run; only initial sampling differs. Local minus uniform mean stage difference: **{comparison['mean_stage_delta_m']:.12f} m**; movement at best-stage solution: **{comparison['mean_movement_delta_m']:.12f} m**. Differences are mixed and small; no superiority, significance, speedup or novelty conclusion is supported.",'','Previous five-seed initial before/after comparisons reproduced the same best-stage distances with the same 1200-evaluation budget. The known adaptive ablation compares two sampling strategies within the same selective problem; it is not a full multi-group/global-reoptimization comparison. S-GCN/weather/counterfactual/human feedback claims remain unimplemented/unvalidated.','','## Unsupported features and scientific limitations','']
    text += ['- '+s for s in limitations]
    text += ['','## Reproducibility, failed runs and freeze','']+['- '+s for s in failed]
    text += ['',f"All failed logs are retained under `{rel(OUT)}`; repeated tests are not counted as additional independent coverage. The older acceptance reports and manifests remain intact. Their old working-source hashes can differ after these explicitly preserved isolated corrections; the new authority is `BACKEND_FREEZE_V1.json`, not a rewritten historical manifest.",'',f"Freeze covers {len(runtime)} runtime/source/checkpoint files; installed package versions and Python are recorded in `{rel(close/'ENVIRONMENT.json')}`. Startup checks hash drift; packages themselves are not vendored or cryptographically frozen. Run commands/actual exit results are in `PP1_BACKEND_FUNCTIONAL_ACCEPTANCE_V1.json`. Raw final TCP proof: `{rel(close/'FROZEN_TCP_RESULT.json')}`.",'','## Frontend integration decision','','The supported local PP1 backend scope is ready for a frontend integration decision. A future interface must expose pending review, measured calibration/evidence, explicit approvals, supported constraints, alternatives, denial/infeasible statuses and source limitations. It must not present unreviewed model candidates as optimization-ready real geometry. Evidence documents currently must be supplied as workspace files by an operator; no generic evidence-document upload, CAD/PDF intake, production auth or planner-feedback-learning workflow is included.','','**Frontend development has not started. Stop here for the user’s decision.**']
    handoff=FINAL/'PP1_BACKEND_FRONTEND_HANDOFF_V1.md';handoff.write_text('\n'.join(text)+'\n',encoding='utf-8')
    (FINAL/'PP1_BACKEND_FUNCTIONAL_ACCEPTANCE_V1.md').write_text('# PP1 independent backend functional acceptance V1\n\nStatus: '+scope+'.\n\nThe complete evidence-linked acceptance and API handoff is [PP1_BACKEND_FRONTEND_HANDOFF_V1.md](PP1_BACKEND_FRONTEND_HANDOFF_V1.md); machine results are [PP1_BACKEND_FUNCTIONAL_ACCEPTANCE_V1.json](PP1_BACKEND_FUNCTIONAL_ACCEPTANCE_V1.json).\n\nFinal checks: 49 existing regression cases pass; 30 handoff cases pass, containing a reexecution of all four supplemental checks. Actual trained-model API outputs, independently computed Pareto objectives/metric transforms, in-search approval revocation, context effects, stored XAI/contracts, ten matched-budget comparison runs and frozen CLI TCP optimization/retrieval are preserved in the referenced raw artifacts. Two pre-change false accepts are reproduced and now rejected. Genuine external review remains absent; no real-venue completion claim.\n',encoding='utf-8')
